<?php
require_once 'includes/config.php';if(empty($_SESSION['student_id'])){header('Location: login.php');exit;}
$q=$dbh->prepare('SELECT s.StudentId,s.StudentName,s.RollId,s.ClassId,c.ClassName,c.Section FROM tblstudents s LEFT JOIN tblclasses c ON c.id=s.ClassId WHERE s.StudentId=:id AND s.Status=1');$q->execute([':id'=>$_SESSION['student_id']]);$student=$q->fetch();if(!$student){unset($_SESSION['student_id']);header('Location: login.php');exit;}
$q=$dbh->prepare('SELECT r.AcademicYear,r.Term,r.ExamType,r.marks,r.MaxMarks,r.Published,s.SubjectName FROM tblresult r JOIN tblsubjects s ON s.id=r.SubjectId WHERE r.StudentId=:id AND r.Published=1 ORDER BY r.AcademicYear DESC,r.Term DESC,r.ExamType,s.SubjectName');$q->execute([':id'=>$student['StudentId']]);$results=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Portal | <?php echo e(srms_school_name());?></title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body><nav class="navbar navbar-default"><div class="container-fluid"><a class="navbar-brand" href="student-dashboard.php"><?php echo e(srms_school_name());?></a><p class="navbar-text navbar-right"><a href="logout.php">Sign out</a></p></div></nav><main class="container srms-page"><div class="panel panel-primary"><div class="panel-body"><img src="profile-photo.php?type=student&id=<?php echo (int)$student['StudentId'];?>" alt="Student profile photo" width="76" height="76" style="float:right;border-radius:50%;object-fit:cover" onerror="this.style.display='none'"><h2><?php echo e($student['StudentName']);?></h2><p>Username: <strong><?php echo e($_SESSION['student_username']);?></strong> · Registration: <?php echo e($student['RollId']);?> · Class: <?php echo e(($student['ClassName']??'').' '.($student['Section']??''));?></p></div></div><div class="panel panel-default"><div class="panel-heading"><strong>Published academic results</strong></div><div class="panel-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Academic year</th><th>Term</th><th>Exam</th><th>Subject</th><th>Marks</th><th>Maximum</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><?php echo e($r['AcademicYear']);?></td><td><?php echo e($r['Term']);?></td><td><?php echo e($r['ExamType']);?></td><td><?php echo e($r['SubjectName']);?></td><td><?php echo e($r['marks']);?></td><td><?php echo e($r['MaxMarks']);?></td></tr><?php endforeach;?><?php if(!$results):?><tr><td colspan="6">No published results are available yet.</td></tr><?php endif;?></tbody></table></div></div></div></main></body></html>